def maxflow(n, edges, s, t, limit):
    """Edmonds-Karp style max flow (independent implementation)."""
    # edges: list of [u, v, cap]
    adj = [[] for _ in range(n)]
    for i, (u, v, c) in enumerate(edges):
        adj[u].append(i); adj[v].append(i+1)
    to = [0]*(2*len(edges))
    cap = [0]*(2*len(edges))
    for i, (u, v, c) in enumerate(edges):
        to[2*i] = v; cap[2*i] = c
        to[2*i+1] = u; cap[2*i+1] = 0
    flow = 0
    while flow < limit:
        parent = [-1]*n
        parent[s] = -2
        q = deque([s])
        while q and parent[t] == -1:
            u = q.popleft()
            for e in adj[u]:
                if cap[e] > 0 and parent[to[e]] == -1:
                    parent[to[e]] = e
                    q.append(to[e])
                    if to[e] == t: break
        if parent[t] == -1: break
        # find bottleneck
        d = limit - flow
        v = t
        while v != s:
            e = parent[v]; d = min(d, cap[e]); v = to[e ^ 1]
        v = t
        while v != s:
            e = parent[v]; cap[e] -= d; cap[e ^ 1] += d; v = to[e ^ 1]
        flow += d
    return flow, cap


